from nlib import *
S=[]
def M(id,title,sc,sm,basics,deeper,expert,facts,dyk,sec="11.5"):
    S.append(N(id,title,"organ","anatomy",sc,sm,basics,deeper,expert,facts,dyk,par=["muscular_system"],made=["skeletal_muscle_tissue"],proc=["muscle_contraction"],mesh=id,refs=[("ANP",sec)],kn=["muscle_contraction","musculoskeletal"]))
M("pectoralis_major","Pectoralis major",0.3,"The large fan-shaped chest muscle that pulls the arm across the body.","This chest muscle swings your arm forward and inward, as when you push or hug.","It runs from the collarbone, sternum and rib cartilages to the upper humerus. It adducts and medially rotates the arm and helps in pushing.","Innervated by the medial and lateral pectoral nerves (C5-T1); clavicular head flexes the shoulder, sternocostal head extends it from a flexed position.",[("Action","Adduct, flex, medially rotate arm"),("Nerve","Pectoral nerves C5-T1")],"In women the breast sits on top of this muscle; it is not itself breast tissue.")
M("deltoid","Deltoid",0.15,"The rounded shoulder muscle that lifts the arm.","The cap of your shoulder; it raises your arm out to the side, forward and back.","Three parts (anterior, middle, posterior) act together to abduct the arm and individually to flex or extend it.","Axillary nerve (C5-C6). Middle fibers are multipennate, giving force for abduction beyond the first ~15° initiated by supraspinatus.",[("Parts","3"),("Nerve","Axillary C5-C6")],"Deltoid injections are common because the muscle is thick and accessible.")
M("biceps_brachii","Biceps brachii",0.28,"The two-headed front-of-arm muscle that bends the elbow and turns the forearm.","Your biceps bends the elbow and also twists the palm up, as when you turn a screwdriver.","It attaches to the shoulder blade and the radius. It is a strong supinator when the elbow is bent.","Musculocutaneous nerve (C5-C6); crosses both shoulder and elbow, so it is biarticular. Distal biceps tendon rupture causes a 'Popeye' bulge.",[("Heads","2 (long, short)"),("Nerve","Musculocutaneous C5-C6")],"Its main job is actually turning the forearm, not just bending the elbow.")
M("triceps_brachii","Triceps brachii",0.3,"The three-headed muscle at the back of the arm that straightens the elbow.","The triceps pushes your arm straight. It is the opposing partner of the biceps.","Its long head also helps extend the shoulder.","Radial nerve (C6-C8); the long head originates on the infraglenoid tubercle, lateral and medial heads from the humeral shaft.",[("Heads","3"),("Nerve","Radial C6-C8")],"Triceps means 'three heads'.")
M("rectus_abdominis","Rectus abdominis",0.35,"The paired strap muscles at the front of the abdomen that bend the trunk.","These are the 'six-pack' muscles; they curl your trunk forward and brace the belly.","Tendinous intersections divide each muscle into segments inside the rectus sheath.","Innervated by thoracoabdominal nerves (T7-T12); critical for intra-abdominal pressure and trunk flexion.",[("Segments","≈ 3-4 per side"),("Nerve","T7-T12")],"The 'six-pack' is just these muscles divided by bands of tissue and shown when body fat is low.","11.4")
M("external_obliques","External obliques",0.3,"The outermost side muscles of the abdomen that twist and bend the trunk.","They run diagonally along your sides and help you twist and lean.","Working on one side bends and rotates to the opposite side. Both sides together flex the trunk and compress the abdomen.","Fibers run in a 'hands in pockets' direction; form inguinal ligament by aponeurosis. Innervated T7-T12.",[("Layer","Outermost of 3 flat muscles"),("Nerve","T7-T12")],"The three layers of flat abdominal muscles run in crossing directions like plywood for strength.","11.4")
M("quadriceps","Quadriceps femoris",0.45,"The four-part front thigh muscle that straightens the knee.","The biggest muscle on the front of your thigh, used to stand up, climb stairs and kick.","Rectus femoris, vastus lateralis, medialis and intermedius share one tendon around the patella.","Femoral nerve (L2-L4); rectus femoris also flexes the hip. It is the largest muscle mass in the body by volume group.",[("Parts","4"),("Nerve","Femoral L2-L4")],"The quadriceps tendon hosts the kneecap, the body's biggest sesamoid bone.","11.6")
M("hamstrings","Hamstrings",0.45,"The three muscles at the back of the thigh that bend the knee and extend the hip.","These muscles pull your heel toward your buttock and help you run.","Biceps femoris, semitendinosus and semimembranosus cross both hip and knee.","Tibial and common fibular divisions of the sciatic nerve (L5-S2); injury is common during sprinting in late swing phase.",[("Muscles","3"),("Nerve","Sciatic L5-S2")],"The name comes from butchers hanging hams by these tendons.","11.6")
M("gastrocnemius","Gastrocnemius",0.4,"The main calf muscle that lifts the heel.","The bulge of your calf; it pushes you up on tiptoe and propels each step.","Its two heads join the Achilles tendon with the soleus.","Tibial nerve (S1-S2). The Achilles tendon stores and returns elastic energy, ~35% of running work comes from tendon recoil.",[("Heads","2"),("Tendon","Achilles")],"The Achilles tendon is the thickest and strongest tendon in the body.","11.6")
M("gluteus_maximus","Gluteus maximus",0.3,"The big buttock muscle that extends the hip.","The largest muscle in the body; it powers climbing, standing up and running.","It extends and rotates the thigh outward and steadies the pelvis.","Inferior gluteal nerve (L5-S2). Insertion into the iliotibial tract and gluteal tuberosity. Its size is linked to human bipedal running.",[("Nerve","Inferior gluteal L5-S2"),("Rank","Largest muscle (by mass)")],"Its large size is an evolutionary signature of upright walking and running.","11.6")
M("trapezius","Trapezius",0.4,"A diamond-shaped muscle across the upper back and neck that moves the shoulder blade.","It lets you shrug and pull your shoulder blades together.","Upper, middle and lower fibers move the scapula up, back and down.","Spinal accessory nerve (CN XI) plus C3-C4. Part of the trapezius derived from branchial arch mesoderm.",[("Nerve","CN XI + C3-C4"),("Fibers","upper, middle, lower")],"Trapezius is named for the trapezoid shape formed by its two halves.","11.5")
M("latissimus_dorsi","Latissimus dorsi",0.4,"The broad back muscle that pulls the arm down and back.","The widest muscle of the back, used for pulling and climbing.","It runs from the lower spine and pelvis to the upper humerus, powering swimming and rowing.","Thoracodorsal nerve (C6-C8); also used in reconstructive flap surgery.",[("Nerve","Thoracodorsal C6-C8"),("Span","≈ 25-40 cm wide")],"Because of its size, surgeons sometimes borrow it to rebuild other body parts.","11.5")
M("sternocleidomastoid","Sternocleidomastoid",0.15,"The thick neck muscle that turns and tilts the head.","Look at the cords running diagonally down your neck when you turn your head; those are sternocleidomastoids.","Acting on one side it tilts the head to that side and rotates the face to the other; together they flex the neck.","Accessory nerve (CN XI) motor, proprioception from C2-C3; congenital torticollis can result from fibrosis.",[("Nerve","CN XI"),("Attachments","sternum, clavicle, mastoid process")],"It also acts as a respiratory accessory muscle during heavy breathing.","11.3")
save("body_muscles",S)
